<span class="line"><span style="color:#101820;">    city</span><span style="color:#68747D;">,</span><span style="color:#101820;"> _ </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> args</span><span style="color:#68747D;">[</span><span style="color:#68747D;">&quot;city&quot;</span><span style="color:#68747D;">].(</span><span style="color:#101820;">string</span><span style="color:#68747D;">)</span></span>
