<span class="line"><span style="color:#101820;">    return nil</span><span style="color:#68747D;">,</span><span style="color:#101820;"> rules</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Wrap</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;custom&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> err</span><span style="color:#68747D;">)</span></span>
